-- F5 BIG-IP: system RAM basis and MIB-verified inventory/health coverage.
-- Additive and idempotent: preserve custom metric definitions and unrelated groups.
DO $migration$
DECLARE p record; patch jsonb := $json$[{"key":"memory","description":"System RAM, TMM data-plane RAM, host non-TMM RAM and swap are separate measurements. System utilization uses sysGlobalHostMemUsed / sysGlobalHostMemTotal; the highest domain percentage is not overall RAM. Swap occupancy alone does not prove active swapping.","metrics":[{"key":"f5_system_mem_total","name":"System RAM Total","oid":"1.3.6.1.4.1.3375.2.1.1.2.20.2.0","type":"gauge","unit":"bytes"},{"key":"f5_system_mem_used","name":"System RAM Used","oid":"1.3.6.1.4.1.3375.2.1.1.2.20.3.0","type":"gauge","unit":"bytes"}]},{"key":"connections","metrics":[{"key":"f5_ssl_handshake_failures","name":"SSL Handshake Failures","oid":"1.3.6.1.4.1.3375.2.1.1.2.9.29.0","type":"counter","unit":"failures/s"},{"key":"f5_tcp_accept_failures","name":"TCP Accept Failures","oid":"1.3.6.1.4.1.3375.2.1.1.2.12.7.0","type":"counter","unit":"failures/s"},{"key":"f5_tcp_connect_failures","name":"TCP Connect Failures","oid":"1.3.6.1.4.1.3375.2.1.1.2.12.9.0","type":"counter","unit":"failures/s"}]},{"key":"virtual_servers","metrics":[{"key":"f5_vs_port","name":"Port","oid":"1.3.6.1.4.1.3375.2.2.10.1.2.1.6","type":"gauge"},{"key":"f5_vs_default_pool","name":"Default pool","oid":"1.3.6.1.4.1.3375.2.2.10.1.2.1.19","type":"string"}]},{"key":"pools","metrics":[{"key":"f5_pool_connections","name":"Connections","oid":"1.3.6.1.4.1.3375.2.2.5.2.3.1.8","type":"gauge","unit":"conns"},{"key":"f5_pool_in_bps","name":"Traffic In","oid":"1.3.6.1.4.1.3375.2.2.5.2.3.1.3","type":"counter","unit":"bps","scale":8},{"key":"f5_pool_out_bps","name":"Traffic Out","oid":"1.3.6.1.4.1.3375.2.2.5.2.3.1.5","type":"counter","unit":"bps","scale":8},{"key":"f5_pool_queue","name":"Connection queue","oid":"1.3.6.1.4.1.3375.2.2.5.2.3.1.18","type":"gauge","unit":"conns"}]},{"key":"ha","metrics":[{"key":"f5_sync_summary","name":"Sync Detail","oid":"1.3.6.1.4.1.3375.2.1.14.1.4.0","type":"string"}]},{"key":"fans","interval_seconds":900,"description":"Physical chassis