ok","text":"Enabled"},"2":{"sev":"info","text":"Disabled"},"3":{"sev":"info","text":"Disabled (parent)"}}},{"key":"f5_member_connections","name":"Connections","oid":"1.3.6.1.4.1.3375.2.2.5.4.3.1.11","type":"gauge","unit":"conns"},{"key":"f5_member_reason","name":"Detail","oid":"1.3.6.1.4.1.3375.2.2.5.6.2.1.8","type":"string"}],"description":"Individual pool members with node, port, health, connections and the device-reported reason. Administrative state is shown separately from availability."},{"key":"nodes","name":"Nodes","kind":"table","interval_seconds":300,"table":{"label_oid":"1.3.6.1.4.1.3375.2.2.4.3.2.1.7"},"metrics":[{"key":"f5_node_avail","name":"Availability","oid":"1.3.6.1.4.1.3375.2.2.4.3.2.1.3","type":"enum","labels":{"0":{"sev":"info","text":"Unknown"},"1":{"sev":"ok","text":"Available"},"2":{"sev":"warn","text":"Degraded"},"3":{"sev":"crit","text":"Offline"},"4":{"sev":"info","text":"No Monitor"},"5":{"sev":"info","text":"Unlicensed"}}},{"key":"f5_node_enabled","name":"Enabled","oid":"1.3.6.1.4.1.3375.2.2.4.3.2.1.4","type":"enum","labels":{"0":{"sev":"info","text":"None"},"1":{"sev":"ok","text":"Enabled"},"2":{"sev":"info","text":"Disabled"},"3":{"sev":"info","text":"Disabled (parent)"}}},{"key":"f5_node_connections","name":"Connections","oid":"1.3.6.1.4.1.3375.2.2.4.2.3.1.9","type":"gauge","unit":"conns"},{"key":"f5_node_reason","name":"Detail","oid":"1.3.6.1.4.1.3375.2.2.4.3.2.1.6","type":"string"}],"description":"Backend node availability and administrative state. A node is distinct from its membership in each pool."},{"key":"disks","name":"Disk partitions","kind":"table","interval_seconds":900,"table":{"label_oid":"1.3.6.1.4.1.3375.2.1.7.3.2.1.1"},"metrics":[{"key":"f5_disk_block_size","name":"Block size","oid":"1.3.6.1.4.1.3375.2.1.7.3.2.1.2","type":"gauge","unit":"bytes"},{"key":"f5_disk_total_blocks","name":"Total blocks","oid":"1.3.6.1.4.1.3375.2.1.7.3.2.1.3","type":"gauge"},{"key":"f5_disk_free_blocks","name":"Free blocks","oid":"1.3.6.1.4.1.3375.2.1.7.3.2.1.4","type":"gauge"}],"description":"Partition utilization is calculated from total and free blocks; byte sizes use each partition's reported block size."},{"key":"certificates","name":"Certificate inventory","kind":"table","interval_seconds":3600,"table":{"label_oid":"1.3.6.1.4.1.3375.2.1.15.1.2.1.1"},"metrics":[{"key":"f5_cert_expiry_text","name":"Expires (UTC)","oid":"1.3.6.1.4.1.3375.2.1.15.1.2.1.4","type":"string"},{"key":"f5_cert_expiry_epoch","name":"Expiry timestamp","oid":"1.3.6.1.4.1.3375.2.1.15.1.2.1.5","type":"gauge","unit":"s"}],"description":"All installed certificate objects, including unused/default certificates. Expiry does not establish that a certificate is bound to active traffic. Days remaining use the appliance clock."},{"key":"modules","name":"Provisioned modules","kind":"table","interval_seconds":3600,"table":{"label_oid":"1.3.6.1.4.1.3375.2.1.11.1.2.1.1"},"metrics":[{"key":"f5_module_level","name":"Provision level","oid":"1.3.6.1.4.1.3375.2.1.11.1.2.1.2","type":"enum","labels":{"1":{"text":"Not provisioned","sev":"info"},"2":{"text":"Minimum","sev":"info"},"3":{"text":"Nominal","sev":"info"},"4":{"text":"Dedicated","sev":"info"},"5":{"text":"Custom","sev":"info"}}},{"key":"f5_module_memory","name":"Memory allocation ratio","oid":"1.3.6.1.4.1.3375.2.1.11.1.2.1.3","type":"gauge","unit":"%"},{"key":"f5_module_cpu","name":"CPU allocation ratio","oid":"1.3.6.1.4.1.3375.2.1.11.1.2.1.4","type":"gauge","unit":"%"}],"description":"Module resource provisioning. Not provisioned is informational and does not indicate a fault."},{"key":"cpu_cores","name":"Host CPU cores","kind":"table","interval_seconds":300,"table":{"label_oid":"1.3.6.1.4.1.3375.2.1.7.5.2.1.3"},"metrics":[{"key":"f5_core_usage","name":"CPU (1m)","oid":"1.3.6.1.4.1.3375.2.1.7.5.2.1.27","type":"gauge","unit":"%"},{"key":"f5_core_iowait","name":"I/O wait (1m)","oid":"1.3.6.1.4.1.3375.2.1.7.5.2.1.26","type":"gauge","unit":"%"},{"key":"f5_core_stolen","name":"Stolen CPU (1m)","oid":"1.3.6.1.4.1.3375.2.1.7.5.2.1.38","type":"gauge","unit":"%"}],"description":"Per-core host CPU, I/O wait and hypervisor stolen time. This complements the separate TMM and host summaries."}]$json$::jsonb;
  groups jsonb; change jsonb; current_group jsonb; next_groups jsonb; metrics jsonb; item jsonb; present boolean;
BEGIN
  FOR p IN SELECT id,oid_groups FROM device_profiles WHERE builtin AND name='F5 BIG-IP' LOOP
    groups := COALESCE(p.oid_groups,'[]'::jsonb);
    FOR change IN SELECT value FROM jsonb_array_elements(patch) LOOP
      SELECT value INTO current_group FROM jsonb_array_elements(groups) WHERE value->>'key'=change->>'key';
      IF current_group IS NULL THEN groups := groups || jsonb_build_array(change);
      ELSE
        metrics := COALESCE(current_group->'metrics','[]'::jsonb);
        FOR item IN SELECT value FROM jsonb_array_elements(change->'metrics') LOOP
          SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(metrics) WHERE value->>'key'=item->>'key') INTO present;
          IF NOT present THEN metrics := metrics || jsonb_build_array(item); END IF;
        END LOOP;
        current_group := current_group || (change - 'metrics') || jsonb_build_object('metrics',metrics);
        SELECT jsonb_agg(CASE WHEN value->>'key'=change->>'key' THEN current_group ELSE value END ORDER BY ord)
          INTO next_groups FROM jsonb_array_elements(groups) WITH ORDINALITY a(value,ord);
        groups := next_groups;
      END IF;
    END LOOP;
    -- Clarify the two existing labels without changing their OIDs or thresholds.
    SELECT jsonb_agg(CASE WHEN g->>'key'='memory' THEN jsonb_set(g,'{metrics}',
      (SELECT jsonb_agg(CASE WHEN m->>'key' IN ('f5_other_mem_used','f5_other_mem_total') AND m->>'name' IN ('Host Memory Used','Host Memory Total')
        THEN jsonb_set(m,'{name}',to_jsonb(replace(m->>'name','Host Memory','Non-TMM Memory'))) ELSE m END ORDER BY mi)
       FROM jsonb_array_elements(g->'metrics') WITH ORDINALITY b(m,mi))) ELSE g END ORDER BY gi)
      INTO groups FROM jsonb_array_elements(groups) WITH ORDINALITY a(g,gi);
    IF groups IS DISTINCT FROM p.oid_groups THEN
      UPDATE device_profiles SET oid_groups=groups,version=version+1,updated_at=now() WHERE id=p.id;
    END IF;
  END LOOP;
END
